export const COLOR_TOKEN_COUNT = colorTokenCategories.reduce(
	(count, category) => count + category.tokens.length,
	0,
)
export const EFFECT_TOKEN_COUNT = effectTokens.length
export const LIVE_PAINT_TOKEN_COUNT = COLOR_TOKEN_COUNT + EFFECT_TOKEN_COUNT
